 *  - onComplete: called once when the timer reaches 0
 */
export default function CountdownTimer({ seconds, autoStart = true, onComplete }) {
  const [remaining, setRemaining] = useState(seconds);
  const [running, setRunning] = useState(autoStart && seconds > 0);

  // Track the absolute end time so the timer doesn't drift when
  // intervals are delayed (e.g. background tabs).
  const endTimeRef = useRef(null);
  const onCompleteRef = useRef(onComplete);
  onCompleteRef.current = onComplete;

